  double totalRotation = (ball.velocity.length() * dt + spinSpeed * dt) * 0.1;

  Vector3 rotationAxis = Vector3(0, 1, 0); // Por padrão, rotação em Y

  // Se houver movimento, inclina a rotação para alinhar com o movimento
  if (ball.velocity.length() > 0) {
    rotationAxis = _getRotationAxis(ball.velocity);
  }

  Quaternion rotation = Quaternion.axisAngle(rotationAxis, totalRotation);

  // Aplica diretamente
  ball.rotation.setFrom(rotation);

  ball.updateTransform();
}
