```dart
class Ball {
  late Object ball;
  double radius = 6.5;
  double velocityX = 0;
  double velocityY = 0;
  double velocityZ = 0;
  double CUSHION_RESTITUTION = 0.8;

  // Rotação angular independente
  double spinSpeed = 0.0; // Velocidade de rotação angular

  void update(double dt, double friction, List<Rectangle> rectangles) {
    // Move a bola
    ball.position.x += velocityX * dt;
    ball.position.y += velocityY * dt;
    ball.position.z += velocityZ * dt;

    // Reduz velocidade
    velocityX *= friction;
    velocityY *= friction;
    velocityZ *= friction;

    // Calcula rotação baseada no movimento
    Vector3 velocity = Vector3(velocityX, velocityY, velocityZ);

    // Eixo de rotação é perpendicular ao movimento
    Vector3 rotationAxis = _getRotationAxis(velocity);

    // Ângulo de rotação proporcional à velocidade
    double angle = Math.max(0, velocity.length()) * dt * 0.1; // Fator de ajuste

    // Se velocidade é muito baixa, rotação menor também
    if (angle < 0.01 && velocity.length() > 0.1) {
      angle = 0.01;
    }

    if (rotationAxis.length > 0) {
      Quaternion rotation = Quaternion.axisAngle(rotationAxis, angle);

      // Aplica rotação atualizando a orientação atual
      ball.rotation.applyQuaternion(rotation);
    }

    // Atualiza transformações
    ball.updateTransform();
  }

  // Função auxiliar para calcular eixo de rotação
  Vector3 _getRotationAxis(Vector3 velocity) {
    // Normalização do vetor de velocidade
    double speed = velocity.length();

    if (speed == 0) return Vector3.zero();

    // Para uma bola, usamos o produto vetorial do movimento com eixo vertical
    // Isso cria uma rotação "spin" natural
    Vector3 upVector = Vector3(0, 0, 1);

    Vector3 rotationAxis = velocity.cross(upVector).normalized();

    // Se o produto cruzado for zero (movimento puramente em Z), use o eixo padrão
    if (rotationAxis.length() < 0.0001) {
      // Retorna um eixo baseado na direção oposta ao movimento
      return velocity.normalized().cross(Vector3(-1, 0, 0)).normalized();
    }

    return rotationAxis;
  }
}
